# EXPERIMENTAL (round 4). Forward score under a contamination-robust predictive density (eps = 0.01, kappa = 25, chosen on development data; kappa = 100 gives the same result there), for M3 and the gated regime model,
# on the 109 recordings of the frozen validation. NOT independent: those recordings had already been seen under the plain density (their two worst tails are what motivated the check), see v2/validation/report.md.
# Endpoint E1r (declared before this run): mean difference regime model minus M3, both under the robust density, non-inferiority margin -0.01, paired bootstrap 10,000. Run: Rscript experiments/regimes/v3/tail_validate.R
source("analysis/00_setup.R"); source("experiments/regimes/v2/lib2.R"); n_cores <- max(1L, min(4L, cfg$cores - 3L)); GATE <- 9; ids <- readLines("experiments/regimes/v2/validation/ids.txt"); d <- load_dataset("exercise", cfg); jobs <- lapply(ids, function(id) list(id = id, rr = d$rr[[id]]))
one <- function(job) {
  series <- prepare_series(job$rr); dy <- series$dy; n <- length(dy); ctl <- series$control; gm <- gate_mult(dy, ctl); n_head <- floor(0.7 * n); sh <- prepare_series(dy[seq_len(n_head)]); lp <- sh$priors$energy_ratio
  bh <- fit_ext(sh); cph <- cp_search(sh, bh, min_gain = -Inf); idx <- (n_head + 1):n; idx <- idx[gm[idx] < ctl$lik_gate_max]; hr <- bh$run(); pp <- bh$p
  r0 <- reg_run(dy, ctl, pp$kp, pp$ks, lp, pp$lR, hr$sig2, hr$nu0, matrix(0, 1, 2), matrix(1, 1, 1), w0 = 1, gm = gm, full = TRUE, eps = 0.01, kappa = 25); out <- list(m3 = mean(r0$logdens[idx]), m3_rob = mean(r0$logdens_rob[idx])); out$hmm <- out$m3; out$hmm_rob <- out$m3_rob
  if (!is.null(cph) && cph$gain >= GATE) { h <- fit_regime(sh, 2, cph, bh, 7, 0.7, recip = 20); if (isTRUE(h$ok)) { p <- h$p; r <- reg_run(dy, ctl, p$kp, p$ks, lp, p$lR, p$sig2, p$nu0, p$mu, p$Pi, gm = gm, full = TRUE, eps = 0.01, kappa = 25); out$hmm <- mean(r$logdens[idx]); out$hmm_rob <- mean(r$logdens_rob[idx]) } }
  as.data.table(c(list(id = job$id, tail_bad = mean(dy[idx] > 2)), out)) }
log_msg("Robust forward score on the validation recordings"); res <- rbindlist(drop_failed(map_recordings(jobs, one, n_cores), "recording")); saveRDS(res, "experiments/regimes/v3/_out/tail_validate.rds")
x <- res[tail_bad < 0.1]; set.seed(1); bs <- function(d) { b <- replicate(10000, mean(d[sample.int(length(d), length(d), TRUE)])); c(est = mean(d), lo = unname(quantile(b, .025)), hi = unname(quantile(b, .975)), p_NI = mean(b <= -0.01), p_sup = mean(b <= 0)) }
cat("\nPlain density (the frozen E1):\n"); print(round(bs(x$hmm - x$m3), 3)); cat("\nRobust density, both models (E1r):\n"); d <- x$hmm_rob - x$m3_rob; print(round(bs(d), 3)); cat("n =", nrow(x), " median", round(median(d), 3), " trimmed mean", round(mean(d, trim = .1), 3), " better in", round(100 * mean(d > 0)), "% worst", round(min(d), 2), "\n")
